//! Fresh-install registration identifiers observed in the comparison APK.
//!
//! These values are generated locally and must be persisted before the first
//! network mutation. This module reproduces the comparison client's fallback
//! path when no Android-derived performance-device identifier or prior backup
//! token exists.

use std::fmt;

use serde::{Deserialize, Serialize};
use zeroize::Zeroizing;

use super::wire::RegistrationCommonParams;
use crate::model::phone::PhoneNumber;
use crate::{Error, Result};

/// Byte length generated by the comparison client's AES-160 helper for both
/// recovery and backup tokens.
pub const COMPARISON_OPAQUE_TOKEN_BYTES: usize = 20;

/// Locally generated inputs shared by comparison registration requests.
///
/// Serialize this value only into the encrypted protocol store. `Debug`
/// reports shapes, never identifiers or token bytes.
#[derive(Serialize, Deserialize)]
pub struct ComparisonRegistrationPrerequisites {
    facebook_device_id: String,
    experiment_id: [u8; 16],
    access_session_id: [u8; 16],
    recovery_token: Zeroizing<Vec<u8>>,
    backup_token: Zeroizing<Vec<u8>>,
}

impl fmt::Debug for ComparisonRegistrationPrerequisites {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("ComparisonRegistrationPrerequisites")
            .field("has_facebook_device_id", &true)
            .field("experiment_id_length", &self.experiment_id.len())
            .field("access_session_id_length", &self.access_session_id.len())
            .field("recovery_token_length", &self.recovery_token.len())
            .field("backup_token_length", &self.backup_token.len())
            .finish()
    }
}

impl ComparisonRegistrationPrerequisites {
    /// Generate the comparison client's fresh-install fallback values.
    pub fn generate() -> Result<Self> {
        let facebook_uuid = random_uuid_v4()?;
        let experiment_id = random_uuid_v4()?;
        let access_session_id = random_uuid_v4()?;
        let mut recovery_token = vec![0u8; COMPARISON_OPAQUE_TOKEN_BYTES];
        let mut backup_token = vec![0u8; COMPARISON_OPAQUE_TOKEN_BYTES];
        fill_random(&mut recovery_token)?;
        fill_random(&mut backup_token)?;
        Ok(Self {
            facebook_device_id: canonical_uuid(facebook_uuid),
            experiment_id,
            access_session_id,
            recovery_token: Zeroizing::new(recovery_token),
            backup_token: Zeroizing::new(backup_token),
        })
    }

    /// Construct the reusable common request parameters from persisted
    /// prerequisites and caller-controlled locale information.
    pub fn common_params(
        &self,
        phone: PhoneNumber,
        language: impl Into<String>,
        locale: impl Into<String>,
    ) -> Result<RegistrationCommonParams> {
        RegistrationCommonParams::new(
            phone,
            language,
            locale,
            self.facebook_device_id.clone(),
            self.experiment_id,
            Some(self.access_session_id),
            self.recovery_token.to_vec(),
            self.backup_token.to_vec(),
        )
    }
}

fn fill_random(output: &mut [u8]) -> Result<()> {
    getrandom::fill(output).map_err(|error| {
        Error::Io(std::io::Error::other(format!(
            "entropy source failed: {error}"
        )))
    })
}

fn random_uuid_v4() -> Result<[u8; 16]> {
    let mut bytes = [0u8; 16];
    fill_random(&mut bytes)?;
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    Ok(bytes)
}

fn canonical_uuid(bytes: [u8; 16]) -> String {
    let hex = hex::encode(bytes);
    format!(
        "{}-{}-{}-{}-{}",
        &hex[0..8],
        &hex[8..12],
        &hex[12..16],
        &hex[16..20],
        &hex[20..32]
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_values_have_observed_shapes_and_redacted_debug() {
        let prerequisites = ComparisonRegistrationPrerequisites::generate().unwrap();
        assert_eq!(prerequisites.facebook_device_id.len(), 36);
        assert_eq!(prerequisites.experiment_id[6] >> 4, 4);
        assert_eq!(prerequisites.experiment_id[8] >> 6, 2);
        assert_eq!(prerequisites.access_session_id[6] >> 4, 4);
        assert_eq!(prerequisites.access_session_id[8] >> 6, 2);
        assert_eq!(prerequisites.recovery_token.len(), 20);
        assert_eq!(prerequisites.backup_token.len(), 20);
        let debug = format!("{prerequisites:?}");
        assert!(!debug.contains(&prerequisites.facebook_device_id));
        assert!(!debug.contains(&hex::encode(&prerequisites.recovery_token)));
    }

    #[test]
    fn serialized_prerequisites_roundtrip_for_encrypted_store_persistence() {
        let prerequisites = ComparisonRegistrationPrerequisites::generate().unwrap();
        let encoded = serde_json::to_vec(&prerequisites).unwrap();
        let decoded: ComparisonRegistrationPrerequisites =
            serde_json::from_slice(&encoded).unwrap();
        assert_eq!(decoded.facebook_device_id, prerequisites.facebook_device_id);
        assert_eq!(decoded.experiment_id, prerequisites.experiment_id);
        assert_eq!(decoded.access_session_id, prerequisites.access_session_id);
        assert_eq!(decoded.recovery_token, prerequisites.recovery_token);
        assert_eq!(decoded.backup_token, prerequisites.backup_token);
    }

    #[test]
    fn common_params_reuse_the_persisted_values() {
        let prerequisites = ComparisonRegistrationPrerequisites::generate().unwrap();
        let first = prerequisites
            .common_params(PhoneNumber::new(1, "5551234567").unwrap(), "en", "US")
            .unwrap();
        let second = prerequisites
            .common_params(PhoneNumber::new(1, "5551234567").unwrap(), "en", "US")
            .unwrap();
        let mut first_form = super::super::wire::RegistrationForm::new();
        let mut second_form = super::super::wire::RegistrationForm::new();
        first.append_to_form(&mut first_form).unwrap();
        second.append_to_form(&mut second_form).unwrap();
        assert_eq!(first_form.encode().unwrap(), second_form.encode().unwrap());
    }
}
